/**
 *  A building: walls on its footprint from the ground to the eave, plus the roof faces on
 *  top (generated from `roof` by `pv-roof`, or placed one by one).
 */
export type Building = Building_Serialize | Building_Deserialize;

/**  Identifies a building. */
export type BuildingId = string;

/**
 *  A building: walls on its footprint from the ground to the eave, plus the roof faces on
 *  top (generated from `roof` by `pv-roof`, or placed one by one).
 */
export type Building_Deserialize = {
	id: BuildingId,
	name: string,
	/**
	 *  Reference point at ground level (world ENU, m): the centre of the footprint for a
	 *  rectangle.
	 */
	origin: [number, number, number],
	/**  Footprint polygon, counter-clockwise, relative to `origin` (east, north), m. */
	footprint: ([number, number])[],
	/**
	 *  Size of the footprint's minimum-area enclosing rectangle (long side first for
	 *  generated roofs), m. Used by the statics (building dimensions `b`, `d`).
	 */
	sizeM: [number, number],
	eaveHeightM: number,
	/**  Ridge height above ground; equals `eave_height_m` for a flat roof. */
	ridgeHeightM: number,
	roofKind: RoofKind,
	/**
	 *  How the roof is generated from the footprint; `None`: roof faces placed one by one
	 *  (imports, presets). `roof_kind`, `ridge_height_m` and `size_m` are then given, not
	 *  derived.
	 */
	roof?: RoofSpec_Deserialize | null,
	/**  Site data for the statics; `None` until the site step fills it. */
	site?: SiteParams | null,
};

/**
 *  A building: walls on its footprint from the ground to the eave, plus the roof faces on
 *  top (generated from `roof` by `pv-roof`, or placed one by one).
 */
export type Building_Serialize = {
	id: BuildingId,
	name: string,
	/**
	 *  Reference point at ground level (world ENU, m): the centre of the footprint for a
	 *  rectangle.
	 */
	origin: [number, number, number],
	/**  Footprint polygon, counter-clockwise, relative to `origin` (east, north), m. */
	footprint: ([number, number])[],
	/**
	 *  Size of the footprint's minimum-area enclosing rectangle (long side first for
	 *  generated roofs), m. Used by the statics (building dimensions `b`, `d`).
	 */
	sizeM: [number, number],
	eaveHeightM: number,
	/**  Ridge height above ground; equals `eave_height_m` for a flat roof. */
	ridgeHeightM: number,
	roofKind: RoofKind,
	/**
	 *  How the roof is generated from the footprint; `None`: roof faces placed one by one
	 *  (imports, presets). `roof_kind`, `ridge_height_m` and `size_m` are then given, not
	 *  derived.
	 */
	roof?: RoofSpec_Serialize | null,
	/**  Site data for the statics; `None` until the site step fills it. */
	site?: SiteParams | null,
};

/**  Who changed the library. */
export type ChangeAuthor = "user" | "import" | "seed" | "copilot";

/**  What a command changed. */
export type ChangeSet = ChangeSet_Serialize | ChangeSet_Deserialize;

/**  What a command changed. */
export type ChangeSet_Deserialize = {
	/**  Modules whose position or state changed. Sorted, unique; empty when `structure`. */
	moduleIds: ModuleId[],
	/**  The project's pricing (discounts) changed. */
	pricing: boolean,
	/**  The frozen components changed (adopted, updated or forgotten). */
	components?: boolean,
	/**  The wiring (inverters, strings, electrical settings) changed. */
	wiring?: boolean,
	/**  The project's location or weather changed. */
	site?: boolean,
	/**  Buildings added, changed or removed. Sorted, unique. */
	buildings: BuildingId[],
	/**  Roof faces added, changed or removed. Sorted, unique. */
	faces: RoofFaceId[],
	/**  Arrays added, changed or removed. Sorted, unique. */
	arrays: ArrayId[],
	/**
	 *  Modules were added or removed for good: ids were renumbered, every module-indexed
	 *  view (GPU buffers, selections) must be rebuilt.
	 */
	structure: boolean,
};

/**  What a command changed. */
export type ChangeSet_Serialize = {
	/**  Modules whose position or state changed. Sorted, unique; empty when `structure`. */
	moduleIds: ModuleId[],
	/**  The project's pricing (discounts) changed. */
	pricing: boolean,
	/**  The frozen components changed (adopted, updated or forgotten). */
	components: boolean,
	/**  The wiring (inverters, strings, electrical settings) changed. */
	wiring: boolean,
	/**  The project's location or weather changed. */
	site: boolean,
	/**  Buildings added, changed or removed. Sorted, unique. */
	buildings: BuildingId[],
	/**  Roof faces added, changed or removed. Sorted, unique. */
	faces: RoofFaceId[],
	/**  Arrays added, changed or removed. Sorted, unique. */
	arrays: ArrayId[],
	/**
	 *  Modules were added or removed for good: ids were renumbered, every module-indexed
	 *  view (GPU buffers, selections) must be rebuilt.
	 */
	structure: boolean,
};

/**  A candidate for an array, with what makes it incompatible (empty: compatible). */
export type Choice = Choice_Serialize | Choice_Deserialize;

/**  A candidate for an array, with what makes it incompatible (empty: compatible). */
export type Choice_Deserialize = {
	summary: ComponentSummary_Deserialize,
	issues: CommandError[],
};

/**  A candidate for an array, with what makes it incompatible (empty: compatible). */
export type Choice_Serialize = {
	summary: ComponentSummary_Serialize,
	issues: CommandError[],
};

/**  A serialisable model change. */
export type Command = Command_Serialize | Command_Deserialize;

/**  A command failure, expressed as an i18n key plus ICU parameters — never as prose. */
export type CommandError = {
	key: string,
	params: { [key in string]: ErrorParam },
};

/**  A serialisable model change. */
export type Command_Deserialize = 
/**  Translates modules in their roof's `(u, v)` frame, metres. */
{ type: "MoveModules"; ids: ModuleId[]; du: number; dv: number } | 
/**  Marks modules as removed (they keep their slot and GPU instance index). */
{ type: "RemoveModules"; ids: ModuleId[] } | 
/**  Marks removed modules as active again. */
{ type: "RestoreModules"; ids: ModuleId[] } | 
/**
 *  Sets exact module positions. Used as the inverse of `MoveModules` so that undo
 *  restores the original coordinates bit for bit (`(u + du) - du != u` in floating point).
 */
{ type: "SetModulePositions"; positions: ModulePosition[] } | 
/**  Sets (`Some`) or removes (`None`) the discount of a manufacturer on the whole project. */
{ type: "SetDiscount"; manufacturer: string; rate?: number | null } | 
/**  Replaces the building with the same id, or inserts it at `at` (clamped; `None`: last). */
{ type: "UpsertBuilding"; building: Building_Deserialize; at?: number | null } | 
/**  Removes a building with its roof faces, arrays and modules. */
{ type: "RemoveBuilding"; id: BuildingId } | 
/**  Replaces the roof face with the same id, or inserts it at `at`. */
{ type: "UpsertRoofFace"; face: RoofFace_Deserialize; at?: number | null } | 
/**  Removes a roof face with its arrays and modules. */
{ type: "RemoveRoofFace"; id: RoofFaceId } | 
/**  Replaces the array with the same id (its modules are kept), or inserts it at `at`. */
{ type: "UpsertArray"; array: PanelArray_Deserialize; at?: number | null } | 
/**  Removes an array with its modules; arrays paired with it are unpaired. */
{ type: "RemoveArray"; id: ArrayId } | 
/**  Replaces all modules of an array. Structural: module ids are renumbered. */
{ type: "SetArrayModules"; array_id: ArrayId; modules: ModuleSlot[] } | 
/**
 *  Freezes library components into the project (identical copies already there are
 *  skipped; a different copy with the same id is refused: use `UpdateComponents`).
 */
{ type: "AdoptComponents"; snapshots: ComponentSnapshot_Deserialize[] } | 
/**  Removes frozen components no array or system refers to. */
{ type: "ForgetComponents"; ids: ComponentId[] } | 
/**
 *  Replaces frozen components (accepted update proposals); arrays using an updated
 *  module get its dimensions.
 */
{ type: "UpdateComponents"; snapshots: ComponentSnapshot_Deserialize[] } | 
/**
 *  Sets the module and mounting system of an array (checked for compatibility; the
 *  module's dimensions are copied, a newly chosen system brings its rail geometry).
 */
{ type: "SetArrayComponents"; array_id: ArrayId; module?: ComponentId | null; mounting?: ComponentId | null } | 
/**  Replaces the project's location and weather. */
{ type: "SetSite"; site: ProjectSite_Deserialize } | 
/**  Replaces the inverters, strings and electrical settings of the project. */
{ type: "SetWiring"; wiring: Wiring_Deserialize } | 
/**  Several commands applied as one, all or nothing. */
{ type: "Batch"; commands: Command_Deserialize[] };

/**  A serialisable model change. */
export type Command_Serialize = 
/**  Translates modules in their roof's `(u, v)` frame, metres. */
{ type: "MoveModules"; ids: ModuleId[]; du: number; dv: number } | 
/**  Marks modules as removed (they keep their slot and GPU instance index). */
{ type: "RemoveModules"; ids: ModuleId[] } | 
/**  Marks removed modules as active again. */
{ type: "RestoreModules"; ids: ModuleId[] } | 
/**
 *  Sets exact module positions. Used as the inverse of `MoveModules` so that undo
 *  restores the original coordinates bit for bit (`(u + du) - du != u` in floating point).
 */
{ type: "SetModulePositions"; positions: ModulePosition[] } | 
/**  Sets (`Some`) or removes (`None`) the discount of a manufacturer on the whole project. */
{ type: "SetDiscount"; manufacturer: string; rate: number | null } | 
/**  Replaces the building with the same id, or inserts it at `at` (clamped; `None`: last). */
{ type: "UpsertBuilding"; building: Building_Serialize; at: number | null } | 
/**  Removes a building with its roof faces, arrays and modules. */
{ type: "RemoveBuilding"; id: BuildingId } | 
/**  Replaces the roof face with the same id, or inserts it at `at`. */
{ type: "UpsertRoofFace"; face: RoofFace_Serialize; at: number | null } | 
/**  Removes a roof face with its arrays and modules. */
{ type: "RemoveRoofFace"; id: RoofFaceId } | 
/**  Replaces the array with the same id (its modules are kept), or inserts it at `at`. */
{ type: "UpsertArray"; array: PanelArray_Serialize; at: number | null } | 
/**  Removes an array with its modules; arrays paired with it are unpaired. */
{ type: "RemoveArray"; id: ArrayId } | 
/**  Replaces all modules of an array. Structural: module ids are renumbered. */
{ type: "SetArrayModules"; array_id: ArrayId; modules: ModuleSlot[] } | 
/**
 *  Freezes library components into the project (identical copies already there are
 *  skipped; a different copy with the same id is refused: use `UpdateComponents`).
 */
{ type: "AdoptComponents"; snapshots: ComponentSnapshot_Serialize[] } | 
/**  Removes frozen components no array or system refers to. */
{ type: "ForgetComponents"; ids: ComponentId[] } | 
/**
 *  Replaces frozen components (accepted update proposals); arrays using an updated
 *  module get its dimensions.
 */
{ type: "UpdateComponents"; snapshots: ComponentSnapshot_Serialize[] } | 
/**
 *  Sets the module and mounting system of an array (checked for compatibility; the
 *  module's dimensions are copied, a newly chosen system brings its rail geometry).
 */
{ type: "SetArrayComponents"; array_id: ArrayId; module: ComponentId | null; mounting: ComponentId | null } | 
/**  Replaces the project's location and weather. */
{ type: "SetSite"; site: ProjectSite_Serialize } | 
/**  Replaces the inverters, strings and electrical settings of the project. */
{ type: "SetWiring"; wiring: Wiring_Serialize } | 
/**  Several commands applied as one, all or nothing. */
{ type: "Batch"; commands: Command_Serialize[] };

/**  The comparison of one project. */
export type Comparison = {
	rows: ComparisonRow[],
	monthlyAcPvsolKwh: number[],
	monthlyAcPvstudioKwh: number[],
	/**  Both simulations ran on PV*SOL's weather file. */
	sameWeather: boolean,
	assumptions: SimulationAssumptions,
};

/**  One compared quantity. */
export type ComparisonRow = {
	/**  Translation key suffix (`pvsol.compare.<key>`). */
	key: string,
	/**  `kWh`, `kWh/m²`, `kWh/kWp`, `%`, `kWp`. */
	unit: string,
	pvsol: number,
	pvstudio: number,
};

/**  One revision of a catalogue entry. */
export type Component = Component_Serialize | Component_Deserialize;

/**  A component with its history and prices. */
export type ComponentDetail = ComponentDetail_Serialize | ComponentDetail_Deserialize;

/**  A component with its history and prices. */
export type ComponentDetail_Deserialize = {
	entry: LibraryEntry_Deserialize,
	revisions: RevisionInfo[],
	prices: PriceEntry_Deserialize[],
};

/**  A component with its history and prices. */
export type ComponentDetail_Serialize = {
	entry: LibraryEntry_Serialize,
	revisions: RevisionInfo[],
	prices: PriceEntry_Serialize[],
};

/**  Family of a component (the `ComponentSpec` tag, for search filters and error messages). */
export type ComponentFamily = "module" | "mountingSystem" | "mountingPart" | "inverter" | "optimizer" | "battery" | "equipment";

/**  Identifies a library component across all its revisions. */
export type ComponentId = string;

/**  A component frozen into a project, with the price it was adopted at. */
export type ComponentSnapshot = ComponentSnapshot_Serialize | ComponentSnapshot_Deserialize;

/**  A component frozen into a project, with the price it was adopted at. */
export type ComponentSnapshot_Deserialize = {
	component: Component_Deserialize,
	/**  `None` when the library had no valid price at adoption. */
	price?: PriceEntry_Deserialize | null,
};

/**  A component frozen into a project, with the price it was adopted at. */
export type ComponentSnapshot_Serialize = {
	component: Component_Serialize,
	/**  `None` when the library had no valid price at adoption. */
	price?: PriceEntry_Serialize | null,
};

/**  Where a component's data comes from. */
export type ComponentSource = 
/**  Entered by hand. */
"manual" | 
/**  Imported from a manufacturer's list (K2 xlsx, CSV). */
"import" | 
/**  Extracted from a datasheet by the copilot; never `verified` until reviewed. */
"aiExtracted";

/**  Family-specific data of a component (closed set). */
export type ComponentSpec = ComponentSpec_Serialize | ComponentSpec_Deserialize;

/**  Family-specific data of a component (closed set). */
export type ComponentSpec_Deserialize = {
	family: "module",
} & ModuleSpec_Deserialize | {
	family: "mountingSystem",
} & MountingSystemSpec_Deserialize | {
	family: "mountingPart",
} & PartSpec_Deserialize | {
	family: "inverter",
} & InverterSpec_Deserialize | {
	family: "optimizer",
} & OptimizerSpec_Deserialize | {
	family: "battery",
} & BatterySpec_Deserialize | {
	family: "equipment",
} & EquipmentSpec_Deserialize;

/**  Family-specific data of a component (closed set). */
export type ComponentSpec_Serialize = {
	family: "module",
} & ModuleSpec_Serialize | {
	family: "mountingSystem",
} & MountingSystemSpec_Serialize | {
	family: "mountingPart",
} & PartSpec_Serialize | {
	family: "inverter",
} & InverterSpec_Serialize | {
	family: "optimizer",
} & OptimizerSpec_Serialize | {
	family: "battery",
} & BatterySpec_Serialize | {
	family: "equipment",
} & EquipmentSpec_Serialize;

/**  One row of a search result (no spec: lists stay light). */
